55	+'use client';
56	+
57	+import { atom } from 'jotai';
58	+import { atomWithStorage } from 'jotai/utils';
59	+
60	+export const userNameAtom = atom<string>('Guest');
61	+
62	+export const userRoleAtom = atomWithStorage<string>('infrafund_user_role', '');
63	+
64	+export const formattedRoleAtom = atom((get) => {
65	+    const role = get(userRoleAtom);
66	+    return formatRoleLabel(role);
67	+});
68	+
69	+function formatRoleLabel(role: string): string {
70	+    const normalized = role.trim().toLowerCase();
71	+    if (!normalized) return 'Member';
72	+
73	+    const roleMap: Record<string, string> = {
74	+        investor: 'Investor',
75	+        contractor: 'Contractor',
76	+        client: 'Project Developer',
77	+        dao: 'Governance Member',
78	+    };
79	+
80	+    return (
81	+        roleMap[normalized] ??
82	+        normalized
83	+            .split(/[_\s-]+/)
84	+            .filter(Boolean)
85	+            .map((word) => word[0].toUpperCase() + word.slice(1))
86	+            .join(' ')
87	+    );
88	+}
