654	+'use client';
655	+
656	+import { useAtom } from 'jotai';
657	+import { useAccount, useParticleAuth } from '@particle-network/connectkit';
658	+import { useEffect, useCallback } from 'react';
659	+import {
660	+    userNameAtom,
661	+    userRoleAtom,
662	+    formattedRoleAtom,
663	+} from '@/atoms/userAtoms';
664	+
665	+export function useUser() {
666	+    const [userName, setUserName] = useAtom(userNameAtom);
667	+    const [selectedRole, setSelectedRole] = useAtom(userRoleAtom);
668	+    const formattedRole = useAtom(formattedRoleAtom)[0];
669	+
670	+    const account = useAccount();
671	+    const { getUserInfo } = useParticleAuth();
672	+
673	+    const loadUserProfile = useCallback(async () => {
674	+        if (account.status !== 'connected') {
675	+            setUserName('Guest');
676	+            return;
677	+        }
678	+
679	+        // Prefer Particle user profile
680	+        try {
681	+            const info = (await Promise.resolve(getUserInfo())) as unknown as Record<string, unknown> | undefined;
682	+
683	+            const profileName =
684	+                (typeof info?.name === 'string' && info.name.trim()) ||
685	+                (typeof info?.nickname === 'string' && info.nickname.trim()) ||
686	+                (typeof info?.email === 'string' && info.email.trim().split('@')[0]) ||
687	+                '';
688	+
689	+            if (profileName) {
690	+                setUserName(profileName);
691	+                return;
692	+            }
693	+        } catch (error) {
694	+            console.warn('Failed to fetch Particle user info:', error);
695	+        }
696	+
697	+        // Fallback to shortened wallet address
698	+        if (account.address) {
699	+            const shortAddress = `${account.address.slice(0, 6)}...${account.address.slice(-4)}`;
700	+            setUserName(shortAddress);
701	+        }
702	+    }, [account.status, account.address, getUserInfo, setUserName]);
703	+
704	+    // Load user profile when account changes
705	+    useEffect(() => {
706	+        loadUserProfile();
707	+    }, [loadUserProfile]);
708	+
709	+    return {
710	+        userName,
711	+        setUserName,
712	+        selectedRole,
713	+        setSelectedRole,
714	+        formattedRole,
715	+        isConnected: account.status === 'connected',
716	+        address: account.address,
717	+        refreshProfile: loadUserProfile,
718	+    };
719	+}
