+export default function PersonalInformation() {
+    const { userName } = useUser();
+    const avatarLabel = userName.trim().charAt(0).toUpperCase() || 'G';
+
+    const [formData, setFormData] = useState({
+        firstName: '',
+        lastName: '',
+        phoneNumber: '',
+        email: '',
+    });
